const handlePedidoALaCocina = (data) => {
  try {
    const orderWithId = { ...data, id: generateUniqueId2() };

    // Accedemos a la fecha del primer producto en el array `products`
    const orderDate = new Date(orderWithId.products[0]?.date).getTime();

    // Verificamos si el pedido tiene una fecha
    if (!orderDate) {
      console.log("No hay fecha en el pedido");
      return;
    }

    // Verificamos si ya hemos procesado un pedido con la misma fecha recientemente
    if (processedOrderDates.has(orderDate)) {
      console.log("Pedido duplicado, no se agrega."); // Muestra mensaje si el pedido ya existe
      return;
    }

    // Si no existe un pedido con la misma fecha, lo agregamos
    setReceiveOrders((prevMessages) => [...prevMessages, { data: orderWithId }]);
    console.log("Pedidos----->", JSON.stringify(orderWithId)); // Muestra el pedido agregado

    // Añadimos la fecha del pedido al mapa
    processedOrderDates.set(orderDate, true);

    // Limpiamos entradas antiguas del mapa después de cierto tiempo (e.g., 5 minutos)
    setTimeout(() => {
      processedOrderDates.delete(orderDate);
    }, 5 * 60 * 1000); // 5 minutos en milisegundos

  } catch (error) {
    console.log("Error:", error); // Manejo del error
  }
};

