          if (tableIndex === -1) {
            setConsoleAdmin(prevState => [...prevState, 'Error la mesa no existe en el array, no se hará ningún cambio']);
            return prevState;
          }
      
          const table = prevState[tableIndex];
      
          // Si la mesa tiene más de una conexión, decrementamos el contador
