const imprimirFacturaMixta = async (id, totalToPay, products) => {
  const ivaTipo = 0.21; // IVA al 21% (por defecto)
  const iva = totalToPay * ivaTipo;
  const baseImponible = totalToPay; // El total sin IVA
  
  // Crear el texto de la factura
  const fecha = new Date().toLocaleDateString('es-ES');
  const numeroFactura = generateUniqueId(); // Generar un número de factura único

  const facturaText = `
    FACTURA DE VENTA

    EMISOR:
    Razón Social: Burger-Shop
    NIF: B12345678
    Dirección: Avenida Siempreviva 123, Madrid, España
    Teléfono: 233534
    Email: blablalb@blabla.com

    COMPRADOR:
    Cliente: ${id}
    NIF/NIE: No identificado
    Dirección: null
    Teléfono: null

    DETALLES DE LA FACTURA:
    Fecha: ${fecha}, Número de factura: ${numeroFactura}

    Productos:
    ${products.map((product, index) => `
      ${index + 1}. ${product.name} - ${product.price} €
    `).join('\n')}

    Subtotal (sin IVA): ${baseImponible} €
    IVA (${ivaTipo * 100}%): ${iva} €
    Total a pagar (IVA incluido): ${totalToPay + iva} €
  `;

  try {
    // Intenta imprimir con ESC/POS si es una impresora térmica
    const device = await navigator.usb.requestDevice({
      filters: [{ vendorId: 0x1234 }] // El identificador de la impresora (reemplázalo con el correcto)
    });

    if (device) {
      await device.open();
      await device.selectConfiguration(1);
      await device.claimInterface(0);
      
      // Imprimir usando ESC/POS
      const encoder = new TextEncoder();
      const data = encoder.encode(facturaText);
      await device.transferOut(1, data);
      
      await device.close();
    }
  } catch (error) {
    console.error("No se pudo imprimir con ESC/POS, intentando con PDF/HTML.", error);
    
    // Si no funciona la impresora térmica, usa PDF o HTML
    const htmlContent = `
      <div style="font-family: Arial, sans-serif; padding: 10px;">
        <h2 style="text-align: center;">FACTURA DE VENTA</h2>
        <p><strong>EMISOR:</strong></p>
        <p>Razón Social: Burger-Shop</p>
        <p>NIF: B12345678</p>
        <p>Dirección: Avenida Siempreviva 123, Madrid, España</p>
        <p>Teléfono: 233534</p>
        <p>Email: blablalb@blabla.com</p>
        
        <p><strong>COMPRADOR:</strong></p>
        <p>Cliente: ${id}</p>
        <p>NIF/NIE: No identificado</p>
        <p>Dirección: null</p>
        <p>Teléfono: null</p>

        <p><strong>DETALLES DE LA FACTURA:</strong></p>
        <p>Fecha: ${fecha}, Número de factura: ${numeroFactura}</p>

        <h3>Productos:</h3>
        <ul>
          ${products.map((product, index) => `
            <li>${product.name} - ${product.price} €</li>
          `).join('')}
        </ul>

        <p><strong>Subtotal (sin IVA):</strong> ${baseImponible} €</p>
        <p><strong>IVA (21%):</strong> ${iva} €</p>
        <p><strong>Total a pagar (IVA incluido):</strong> ${totalToPay + iva} €</p>
      </div>
    `;

    // Crear una ventana de impresión para una impresora normal
    const printWindow = window.open('', '', 'height=400,width=600');
    printWindow.document.write(htmlContent);
    printWindow.document.close();
    printWindow.print();
  }
};



