import React from 'react'

function BarNavAdmins({setVisiilityComments ,setVisibilityPeopleAcceptConditions, setVisibilityRamRegister,setVisibilityBd, setVisibilityEstadistica, setVisibilityRegistro}) {
    const functionVisibilityRamRegister = () => {
        setVisibilityBd(false)
        setVisibilityEstadistica(false)
        setVisibilityRegistro(false)
        setVisibilityRamRegister(true)
        setVisibilityPeopleAcceptConditions(false)
       setVisiilityComments(false)
    }

    const functionVisibilityBD = () => {
    setVisibilityBd(true)
    setVisibilityEstadistica(false)
    setVisibilityRegistro(false)
    setVisibilityRamRegister(false)
    setVisiilityComments(false)
    
    setVisibilityPeopleAcceptConditions(false)
}
const functionVisibilityEstadistica = () => {
    setVisibilityBd(false)
    setVisibilityEstadistica(true)
    setVisibilityRegistro(false)
    setVisibilityRamRegister(false)
    setVisiilityComments(false)
    
    setVisibilityPeopleAcceptConditions(false)
}
const functionVisibilityRegistro = () => {
    setVisibilityBd(false)
    setVisibilityEstadistica(false)
    setVisibilityRegistro(true)
    setVisibilityRamRegister(false)
    setVisiilityComments(false)
    
    setVisibilityPeopleAcceptConditions(false)
}


const functionVisibilityAcceptConditions = () => {
    setVisibilityBd(false)
    setVisibilityEstadistica(false)
    setVisibilityRegistro(false)
    setVisibilityRamRegister(false)
    setVisiilityComments(false)
    
    setVisibilityPeopleAcceptConditions(true)

}
const functionVisibilityComments = () => {
    setVisibilityBd(false)
    setVisibilityEstadistica(false)
    setVisibilityRegistro(false)
    setVisibilityRamRegister(false)
    setVisiilityComments(true)
    
    setVisibilityPeopleAcceptConditions(false)

}
    return (
    <div className='container-barnav-admins-platform'>
        <nav className='banvav-platform'>
        <button onClick={() => functionVisibilityRegistro()}>Registrar</button>
        <button onClick={() => functionVisibilityBD()}>BD</button>
        <button onClick={() => functionVisibilityEstadistica()}>Estadisticas</button>
       <button onClick={() => functionVisibilityRamRegister()}>Servidores</button>
        <button onClick={() => functionVisibilityAcceptConditions()}>Consentimientos</button>
        <button onClick={() => functionVisibilityComments()}>Sugerencias</button>
        </nav>
    </div>
  )
}

export default BarNavAdmins