import React from 'react'
import { useState, useEffect } from 'react'
function Sugerencias({apiCentral}) {
const [data, setData] = useState()

useEffect(() => {
fetch(`${apiCentral}/getcomments`).then(res => res.json()).then(datos => setData(datos))
}, [])
  return (
    <div className='container-comments-impresion'>
        {data && data.map((date, index) => {
<div key={index}>
<h1>{date.comment}</h1>
<p>{date.date}</p>
</div>
        })}
    </div>
  )
}

export default Sugerencias